const navToggle=document.getElementById("nav-toggle"),primaryNav=document.getElementById("primary-nav");function closeNav(){primaryNav.classList.remove("is-open"),navToggle.setAttribute("aria-expanded","false")}function toggleNav(){const e=primaryNav.classList.toggle("is-open");navToggle.setAttribute("aria-expanded",String(e))}navToggle.addEventListener("click",toggleNav),primaryNav.querySelectorAll("a").forEach(e=>{e.addEventListener("click",closeNav)}),window.addEventListener("resize",()=>{window.innerWidth>640&&closeNav()});const signupForm=document.getElementById("signup-form"),formStatus=document.getElementById("form-status");signupForm.addEventListener("submit",e=>{e.preventDefault();const t=document.getElementById("email").value.trim();t&&(formStatus.textContent=`You're on the list — we'll email ${t} when tracks open.`,signupForm.reset())});